function renderEmailBody(title, message, cta = "") {
  return `
    <div style="font-family:Arial,sans-serif;background:#f5f1e8;padding:24px;color:#17321f">
      <div style="max-width:640px;margin:0 auto;background:#ffffff;border-radius:16px;padding:24px;border:1px solid #d5e3cf">
        <p style="margin:0 0 8px;font-size:12px;letter-spacing:0.14em;text-transform:uppercase;color:#62864e">Smart Agriculture</p>
        <h1 style="margin:0 0 12px;font-size:28px;color:#17321f">${title}</h1>
        <p style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#36503f">${message}</p>
        ${cta ? `<p style="margin:0;font-size:14px;color:#4e6a57">${cta}</p>` : ""}
      </div>
    </div>
  `;
}
async function notifyUser({
  userId,
  type = "lifecycle",
  level = "medium",
  title,
  message,
  source = "system",
  metadata = {},
  sendEmailNotice = false,
  emailSubject = title
}) {
  const alertPayload = {
    userId,
    type,
    level,
    title,
    message,
    source,
    metadata
  };
  let alert = null;
  if (shouldStoreAlert(alertPayload)) {
    alert = await addAlert(alertPayload);
  }
  const user3 = await getUserRecordById(userId);
  let emailLog = null;
  let ownerEmailLog = null;
  if (sendEmailNotice && user3?.email) {
    emailLog = await sendEmail({
      to: user3.email,
      subject: emailSubject,
      text: `${title}

${message}`,
      html: renderEmailBody(title, message, user3.phone ? `Registered phone on file: ${user3.phone}` : ""),
      category: source
    });
  }
  const ownerEmail2 = String(process.env.OWNER_EMAIL || process.env.SMTP_USER || "").trim().toLowerCase();
  if (sendEmailNotice && ownerEmail2 && ownerEmail2 !== user3?.email) {
    ownerEmailLog = await sendEmail({
      to: ownerEmail2,
      subject: `[Owner Alert] ${emailSubject}`,
      text: `Alert for user: ${user3?.name || "Unknown"} (${user3?.phone || "No phone"})

${title}

${message}`,
      html: renderEmailBody(`[Owner Alert] ${title}`, `${message}<br><br><b>User:</b> ${user3?.name || "Unknown"} (${user3?.phone || "No phone"})`, "Action required: Review in Owner Console"),
      category: `owner-${source}`
    });
  }
  return {
    alert,
    emailLog,
    ownerEmailLog,
    contact: user3 ? {
      email: user3.email,
      phone: user3.phone
    } : null
  };
}

